import {mapGetters} from "vuex";
import AddOrUpdate from '@/views/job/components/scheduleForm.vue'
import ScheduleLog from '@/views/job/components/schedule-log.vue'
import request from "@/router/axios";

export default {
  components: {AddOrUpdate, ScheduleLog},
  data() {
    return {
      dataForm: {
        beanName: ''
      },
      tableHeight: undefined,
      dataList: [],
      jobId: '',
      pageIndex: 1,
      pageSize: 10,
      totalPage: 0,
      dataListLoading: false,
      dataListSelections: [],
      addOrUpdateVisible: false,
      logVisible: false
    };
  },
  computed: {
    ...mapGetters(["permission", "userInfo", "userDetail"]),
  },
  mounted() {
    // 设置页面元素高度
    this.setPageContentHeight()
    // 设置表格高度
    this.setTableHeight()
    //加载数据
    this.getDataList()
  },
  methods: {

    // 设置表格高度
    setTableHeight() {
      let pageBody = document.getElementsByClassName('page_body')
      // console.log(78, pageBody[0].offsetHeight - 100)
      this.tableHeight = pageBody[0].offsetHeight - 50 + 'px'
    },
    // 获取数据列表
    getDataList() {
      this.dataListLoading = true
      request({
        url: '/api/idevelop-data/sys/schedule/list',
        method: 'get',
        params: {
          'current': this.pageIndex,
          'size': this.pageSize,
          'beanName': this.dataForm.beanName,
          'remark': this.dataForm.remark,
          'type': this.dataForm.type
        }
      }).then(({data}) => {
        // console.log(data)
        if (data) {
          this.dataList = data.records
          this.totalPage = data.total
        } else {
          this.dataList = []
          this.totalPage = 0
        }
        this.dataListLoading = false
      })
    },
    // 每页数
    sizeChangeHandle(val) {
      this.pageSize = val
      this.pageIndex = 1
      this.getDataList()
    },
    // 当前页
    currentChangeHandle(val) {
      this.pageIndex = val
      this.getDataList()
    },
    // 多选
    selectionChangeHandle(val) {
      this.dataListSelections = val
    },
    // 新增 / 修改
    addOrUpdateHandle(id) {
      this.addOrUpdateVisible = true
      this.$nextTick(() => {
        this.$refs.addOrUpdate.init(id)
      })
    },
    // 删除
    deleteHandle(id) {
      var ids = id ? [id] : this.dataListSelections.map(item => {
        return item.jobId
      })
      this.$confirm(`确定对[id=${ids.join(',')}]进行[${id ? '删除' : '批量删除'}]操作?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        let jobIds = ids;
        request({
          url: '/api/idevelop-data/sys/schedule/delete',
          method: 'post',
          params: {jobIds: jobIds},
          data: {jobIds: jobIds}
        }).then(({data}) => {
          if (data) {
            this.$message({
              message: '操作成功',
              type: 'success',
              duration: 1500,
            })
            this.getDataList()
          } else {
            this.$message.error(data.msg)
          }
        })
      }).catch(() => {
      })
    },
    // 暂停
    pauseHandle(id) {
      var ids = id ? [id] : this.dataListSelections.map(item => {
        return item.jobId
      })
      this.$confirm(`确定对[id=${ids.join(',')}]进行[${id ? '暂停' : '批量暂停'}]操作?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        let jobIds = ids;
        request({
          url: '/api/idevelop-data/sys/schedule/pause',
          method: 'post',
          data: {jobIds: jobIds}
        }).then(({data}) => {
          if (data) {
            this.$message({
              message: '操作成功',
              type: 'success',
              duration: 1500,
            })
            this.getDataList()
          } else {
            this.$message.error(data.msg)
          }
        })
      }).catch(() => {
      })
    },
    // 恢复
    resumeHandle(id) {
      var ids = id ? [id] : this.dataListSelections.map(item => {
        return item.jobId
      })
      this.$confirm(`确定对[id=${ids.join(',')}]进行[${id ? '恢复' : '批量恢复'}]操作?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        let jobIds = ids;
        request({
          url: '/api/idevelop-data/sys/schedule/resume',
          method: 'post',
          data: {jobIds: jobIds}
        }).then(({data}) => {
          if (data) {
            this.$message({
              message: '操作成功',
              type: 'success',
              duration: 1500,
            })
            this.getDataList()
          } else {
            this.$message.error(data.msg)
          }
        })
      }).catch(() => {
      })
    },
    // 立即执行
    runHandle(id) {
      // let lsParams = {
      //   deviceCategoryCode: 'aa', // 设备分类
      //   deviceTypeCode: 'aa', // 设备类型
      //   deviceStatusCode: 'aa', // 设备状态
      //   area: 'aa', // 区域
      //   querySize: 1000, // 前端单次最大同步量（int类型）
      //   executeRuleId: 34 // 执行的规则id(int类型)
      // };
      // console.log(JSON.stringify(lsParams))
      // return;
      //{"deviceCategoryCode":"aa","deviceTypeCode":"aa","deviceStatusCode":"aa","area":"aa","querySize":1000,"executeRuleId":34}


      var ids = id ? [id] : this.dataListSelections.map(item => {
        return item.jobId
      })
      this.$confirm(`确定对[id=${ids.join(',')}]进行[${id ? '立即执行' : '批量立即执行'}]操作?`, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        let jobIds = ids;
        request({
          url: '/api/idevelop-data/sys/schedule/run',
          method: 'post',
          data: {
            jobIds: jobIds,
          }
        }).then(({data}) => {
          if (data) {
            this.$message({
              message: '操作成功',
              type: 'success',
              duration: 1500,
            })
            this.getDataList()
          } else {
            this.$message.error(data.msg)
          }
        })
      }).catch(() => {
      })
    },
    // 日志列表
    logHandle(id) {
      this.jobId = id || '';
      this.logVisible = true
      this.$nextTick(() => {
        this.$refs.log.init()
      })
    }
  }
}
